// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.startPrank(actor, actor);
        bool ok;
        try c.wager{value: 0}() { ok = true; } catch { ok = false; }
        vm.stopPrank();
        assertTrue(ok);
    }
}
